def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        color = max(set(row), key=row.count)
        k = 0
        while k < len(row) and row[k] == color:
            k += 1
        if k > len(row) // 2 and k < len(row):
            for c in range(k, len(row)):
                out[r][c] = 1
    return out
